def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    remaining = 100 - n
    denom = max(1, n - 1)

    opp_c = 0
    my_c = 0
    w_c = 0.0
    w_sum = 0.0
    for i in range(n):
        m, o = history[i]
        w = 1.0 + (i / denom) * 2.0
        w_sum += w
        if o == 'C':
            opp_c += 1
            w_c += w
        if m == 'C':
            my_c += 1

    opp_rate = opp_c / n
    w_rate = w_c / w_sum if w_sum > 0 else 0.5
    my_rate = my_c / n

    rw = n if n < 16 else 16
    rs = n - rw
    rec_c = 0
    rec_m_c = 0
    for i in range(rs, n):
        m, o = history[i]
        if o == 'C':
            rec_c += 1
        if m == 'C':
            rec_m_c += 1
    rec_rate = rec_c / rw if rw > 0 else 0.5
    rec_m_rate = rec_m_c / rw if rw > 0 else 0.5

    ts = max(1, n - 16)
    c_cc = c_count = d_dc = d_count = mimic_m = mimic_t = 0
    for i in range(ts, n):
        pm = history[i - 1][0]
        co = history[i][1]
        mimic_t += 1
        if co == pm:
            mimic_m += 1
        if pm == 'C':
            c_count += 1
            if co == 'C':
                c_cc += 1
        else:
            d_count += 1
            if co == 'C':
                d_dc += 1

    p_cifc = c_cc / c_count if c_count > 0 else rec_rate
    p_cifd = d_dc / d_count if d_count > 0 else rec_rate
    mimic = mimic_m / mimic_t if mimic_t > 0 else 0.5

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    pre_cc = 0
    start = n - streak_d - 1
    while start >= 0:
        m, o = history[start]
        if m == 'C' and o == 'C':
            pre_cc += 1
            start -= 1
        else:
            break

    hostile = False
    if opp_c == 0:
        hostile = True
    elif n >= 8 and rec_rate < 0.18 and p_cifc < 0.30:
        hostile = True
    elif n >= 12 and streak_d >= 6 and rec_rate < 0.35:
        hostile = True

    retaliatory = False
    exploitable = False
    if n >= 6:
        if d_count >= 2 and p_cifd <= 0.40 and p_cifc >= 0.55 and mimic >= 0.65:
            retaliatory = True
        if d_count >= 3 and p_cifd >= 0.70 and rec_rate >= 0.35 and (mimic < 0.80 or rec_rate >= 0.80):
            exploitable = True
        if d_count >= 5 and p_cifd >= 0.62 and p_cifc >= 0.45:
            exploitable = True

    if hostile:
        return 'D'

    if remaining <= 1:
        return 'D'

    if remaining == 2:
        if opp_last == 'D':
            if p_cifc >= 0.45 and (pre_cc >= 5 or w_rate > 0.45) and rec_rate > 0.30:
                return 'C'
            return 'D'
        else:
            if retaliatory:
                return 'C'
            if exploitable or rec_rate >= 0.75:
                if not (p_cifd <= 0.35 and p_cifc >= 0.60):
                    return 'D'
            if w_rate > 0.55 and p_cifd > 0.40:
                return 'D' if rng.random() < 0.75 else 'C'
            return 'C' if rng.random() < 0.65 else 'D'

    if opp_last == 'D':
        if pre_cc == 0 and rec_rate < 0.40:
            return 'D'
        if exploitable:
            return 'D'

        friendly = ((pre_cc >= 8 and rec_rate >= 0.35) or
                    (w_rate > 0.65 and rec_rate > 0.35 and p_cifc > 0.50))

        if streak_d == 1:
            if friendly and rng.random() < 0.30:
                return 'C'
            return 'D' if rng.random() < 0.72 else 'C'

        if streak_d == 2:
            if friendly:
                return 'C' if rng.random() < 0.88 else 'D'
            if w_rate > 0.45 or rec_rate > 0.30:
                return 'C' if rng.random() < 0.55 else 'D'
            return 'D'

        if streak_d == 3:
            if friendly:
                return 'C' if rng.random() < 0.90 else 'D'
            if w_rate > 0.40:
                return 'C' if rng.random() < 0.35 else 'D'
            return 'D'

        if streak_d == 4:
            if friendly and rec_rate > 0.25:
                return 'C' if rng.random() < 0.80 else 'D'
            return 'D'

        if friendly and rec_rate > 0.55 and p_cifc > 0.65 and rng.random() < 0.15:
            return 'C'
        return 'D'

    if retaliatory:
        if remaining <= 4 and w_rate > 0.80 and exploitable:
            return 'D' if rng.random() < 0.45 else 'C'
        return 'C'

    if exploitable:
        if remaining <= 6:
            return 'D' if rng.random() < 0.85 else 'C'
        if rec_rate >= 0.70 or w_rate >= 0.70:
            return 'D' if rng.random() < 0.65 else 'C'
        return 'C' if rng.random() < 0.35 else 'D'

    if remaining <= 4:
        if w_rate > 0.60:
            return 'D' if rng.random() < 0.55 else 'C'
        if w_rate < 0.35:
            return 'D' if rng.random() < 0.65 else 'C'
        return 'C' if rng.random() < 0.55 else 'D'

    if opp_c == n:
        if n > 12 and rng.random() < 0.08:
            return 'D'
        if n > 35 and rng.random() < 0.18:
            return 'D'
        if n > 70 and rng.random() < 0.45:
            return 'D'
        return 'C'

    if rec_rate >= 0.75 and p_cifc >= 0.60:
        if n > 25 and rng.random() < 0.03:
            return 'D'
        return 'C'

    if rec_rate < 0.35:
        return 'D' if rng.random() < 0.70 else 'C'

    if my_last == 'D' and rng.random() < 0.25:
        return 'D'

    return 'C'
